import{_ as t,o as e,c as l,a2 as r}from"./chunks/framework.DnrXFDHb.js";const g=JSON.parse('{"title":"训练、微调与对齐","description":"梳理预训练、监督微调、偏好学习与安全对齐的作用、数据要求、局限及彼此关系。","frontmatter":{"description":"梳理预训练、监督微调、偏好学习与安全对齐的作用、数据要求、局限及彼此关系。"},"headers":[],"relativePath":"llm/training-alignment.md","filePath":"llm/training-alignment.md","lastUpdated":1788365664000}'),i={name:"llm/training-alignment.md"};function n(s,a,o,d,h,p){return e(),l("div",null,[...a[0]||(a[0]=[r(`<h1 id="训练、微调与对齐" tabindex="-1">训练、微调与对齐 <a class="header-anchor" href="#训练、微调与对齐" aria-label="Permalink to &quot;训练、微调与对齐&quot;">​</a></h1><blockquote><p><strong>一句话结论：</strong> 预训练让模型获得通用语言能力，指令微调（SFT）让它学会按指令完成任务，RLHF、DPO 等对齐方法让输出更符合人类偏好与安全边界；能力不等于听话，三个阶段解决的是不同问题。</p></blockquote><h2 id="前置知识" tabindex="-1">前置知识 <a class="header-anchor" href="#前置知识" aria-label="Permalink to &quot;前置知识&quot;">​</a></h2><ul><li>已阅读 <a href="/llm/basics">大模型入门</a>，知道 LLM 的核心任务是预测下一个 Token，以及预训练、微调、对齐的整体流程。</li><li>不要求强化学习或概率论基础，本页只建立直觉。</li><li>先接受一个边界：本页讲各阶段的目标、数据形态和取舍，不涉及具体训练操作、工具选择或调参技巧。</li></ul><h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><p>读完后，你应该能够：</p><ul><li>说明预训练解决了什么问题，又留下哪些缺口。</li><li>解释指令微调（SFT）的数据形态和作用边界。</li><li>用直觉语言区分 RLHF 与 DPO 两种对齐方法。</li><li>解释为什么能力强的模型仍需要对齐。</li><li>判断一个需求更适合微调还是 RAG。</li></ul><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><h3 id="预训练-能力从哪来-缺口在哪" tabindex="-1">预训练：能力从哪来，缺口在哪 <a class="header-anchor" href="#预训练-能力从哪来-缺口在哪" aria-label="Permalink to &quot;预训练：能力从哪来，缺口在哪&quot;">​</a></h3><p>预训练通常使用海量文本、代码或多模态数据，目标是预测下一个 Token。这个阶段决定了模型的基础能力：</p><ul><li>语言表达。</li><li>常识和知识关联。</li><li>代码结构。</li><li>多语言能力。</li><li>基础推理模式。</li></ul><p>还要注意：预训练学到的是“语料里怎么写”，不是“什么是对的”。语料中的错误、过时说法和偏见，也会一并被学进参数。</p><p>但预训练结束时的模型只会“续写”：你问它问题，它可能接着写出一串新问题，或者像模像样地编一个答案。它不知道应该按用户指令行事，也不知道如何拒绝不合适的请求。缺口主要有三类：<strong>指令遵循</strong>、<strong>安全边界</strong>、<strong>稳定的表达习惯</strong>。补齐它们，靠的是后面两个阶段。</p><h3 id="指令微调-sft-从-会续写-到-会做事" tabindex="-1">指令微调（SFT）：从“会续写”到“会做事” <a class="header-anchor" href="#指令微调-sft-从-会续写-到-会做事" aria-label="Permalink to &quot;指令微调（SFT）：从“会续写”到“会做事”&quot;">​</a></h3><p>**指令微调（SFT，Supervised Fine-Tuning）**使用“指令-回答”成对数据：给模型看一条指令和一份高质量回答，让它学会在这种输入下产出类似输出。</p><p>一条典型数据长这样：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>指令：把下面这段话总结成一句话。</span></span>
<span class="line"><span>回答：（一份准确、简洁的高质量总结）</span></span></code></pre></div><p>用这样的数据训练后，模型通常会改善：</p><ul><li>回答问题、分步骤解释。</li><li>遵守输出格式。</li><li>改写、总结、翻译等任务型请求。</li><li>根据上下文完成任务。</li></ul><p>三个关键认知：</p><ul><li>SFT 不是把知识塞进模型。它的数据量远小于预训练，更多是在教模型“如何使用”预训练中已经学到的能力。</li><li>SFT 数据的质量比数量更重要：覆盖面足够、回答可靠的示例，往往比大量粗糙样本更有效。</li><li>SFT 只示范了“好回答长什么样”，没有直接告诉模型“哪个回答更好”。好与坏之间的边界，要靠对齐阶段来刻画。</li></ul><h3 id="对齐-rlhf-和-dpo-在做什么" tabindex="-1">对齐：RLHF 和 DPO 在做什么 <a class="header-anchor" href="#对齐-rlhf-和-dpo-在做什么" aria-label="Permalink to &quot;对齐：RLHF 和 DPO 在做什么&quot;">​</a></h3><p>**对齐（Alignment）**的目标是让模型输出符合人类偏好：有帮助（helpful）、诚实（honest）、无害（harmless）。为什么能力强的模型仍需要对齐？因为能力本身是中立的：一个会写代码的模型同样会写钓鱼邮件，一个博学的模型也可能编造引用、语气伤人。能力越高，“不听话”的代价越大。</p><p>**RLHF（基于人类反馈的强化学习，Reinforcement Learning from Human Feedback）**的直觉分三步：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 让模型对同一个问题生成多个回答</span></span>
<span class="line"><span>2. 人类标注员比较回答的好坏，形成偏好数据</span></span>
<span class="line"><span>3. 用偏好数据训练奖励模型给回答打分，</span></span>
<span class="line"><span>   再用强化学习让主模型生成更高分的回答</span></span></code></pre></div><p>**奖励模型（Reward Model）**把零散的“人类觉得哪个好”变成可以自动计算的分数。为什么偏好数据用“成对比较”而不是直接打分？因为让标注员判断“两个回答哪个更好”，比给绝对分数更容易保持一致。而有了奖励模型，就不需要人工实时打分——人工太慢、太贵，也没法嵌进训练循环；它学过人类偏好，可以低成本地给海量候选回答自动打分，强化学习才能大规模运转。</p><p>**DPO（Direct Preference Optimization，直接偏好优化）**使用同样的偏好数据，但跳过显式的奖励模型，直接用“好回答应当优于坏回答”的比较信号调整模型参数。流程更简单、训练更稳定，是近年常见的替代方案之一。</p><p>对齐决定模型“愿意回答什么”和“怎么回答”，但它不能替代事实验证：对齐后的模型仍然可能出错。</p><h3 id="对齐的代价-遗忘与权衡" tabindex="-1">对齐的代价：遗忘与权衡 <a class="header-anchor" href="#对齐的代价-遗忘与权衡" aria-label="Permalink to &quot;对齐的代价：遗忘与权衡&quot;">​</a></h3><ul><li><strong>灾难性遗忘（Catastrophic Forgetting）</strong>：模型在学习新任务时，原有能力可能明显下降。例如猛灌领域数据后，通用对话能力反而变差。常见缓解思路是把通用数据混进训练，让新旧能力互相牵制。</li><li><strong>帮助与安全的张力</strong>：更愿意回答通常意味着更有帮助，但更容易输出风险内容；更谨慎则可能频繁拒答。对齐就是在这两端之间找平衡点。</li><li><strong>对齐可能带税</strong>：对齐后的模型在一些基准任务上可能比原始版本略差或更保守，这个现象常被称作“对齐税”。评估时要同时看能力指标和行为指标，不能只看单次演示。</li><li><strong>对齐不是铜墙铁壁</strong>：精心构造的对抗输入（常见说法是“越狱”）仍可能绕过防线，因此对齐不能替代内容审核、权限控制和人机边界设计。</li></ul><p>判断一次微调或对齐是否有效，要靠一组代表性样例做评估：正确率、格式稳定性、换一种问法的鲁棒性、拒答质量，以及成本和延迟。没有评估，就无法区分“真的变好”和“看起来变好”。</p><h2 id="最小推演-偏好数据长什么样" tabindex="-1">最小推演：偏好数据长什么样 <a class="header-anchor" href="#最小推演-偏好数据长什么样" aria-label="Permalink to &quot;最小推演：偏好数据长什么样&quot;">​</a></h2><p>奖励模型的训练数据来自“比较”，而不是直接打分。假设对同一个问题，模型生成了三个回答：</p><p>问题：“帮我写一条周末爬山的朋友圈文案。”</p><table tabindex="0"><thead><tr><th>回答</th><th>内容概述</th><th>人类判断</th></tr></thead><tbody><tr><td>A</td><td>通顺、有画面感，没有多余承诺</td><td>明显最好</td></tr><tr><td>B</td><td>通顺，但全是套话</td><td>一般</td></tr><tr><td>C</td><td>写得好，但编造了“景区今天免票”</td><td>最差，有事实错误</td></tr></tbody></table><p>三个回答可以组成三个偏好对：A 优于 B、A 优于 C、B 优于 C（3 × 2 ÷ 2 = 3 对）。一般地，n 个回答能组成 n × (n − 1) ÷ 2 个偏好对。成千上万条这样的比较记录，就是偏好数据的基本形态；用它们训练出的奖励模型，会学会给“人类会喜欢的回答”打高分。</p><p>实际标注中也常先给一组回答排序，再把排序拆成相邻的两两比较，效果类似，这里不展开。</p><p>这个推演只说明偏好数据和奖励模型的来源，不等于线上回答时由人工逐条打分——模型上线后，打分的是训练好的奖励模型（如果用 DPO，则连奖励模型也不需要），人工标注只发生在训练数据准备阶段。</p><h2 id="对比表" tabindex="-1">对比表 <a class="header-anchor" href="#对比表" aria-label="Permalink to &quot;对比表&quot;">​</a></h2><p>三种方法都在教模型“输出得更好”，但训练信号和成本差别很大：</p><table tabindex="0"><thead><tr><th>方法</th><th>训练信号</th><th>数据形态</th><th>实现成本</th><th>主要风险</th></tr></thead><tbody><tr><td>SFT</td><td>直接模仿示例答案</td><td>“指令-回答”成对示例</td><td>较低，有成对标注即可</td><td>只会模仿示范，好坏边界仍然模糊</td></tr><tr><td>RLHF</td><td>奖励模型给出的分数</td><td>人类偏好比较 + 奖励模型</td><td>高，要训练奖励模型且流程复杂</td><td>奖励被钻空子，训练不稳定</td></tr><tr><td>DPO</td><td>直接来自偏好比较</td><td>人类偏好比较对</td><td>中，省去奖励模型，流程更简单</td><td>依赖偏好数据质量，仍可能过度优化</td></tr></tbody></table><p>三者经常组合使用：SFT 打底，再用 RLHF 或 DPO 完成对齐。</p><h2 id="常见误区" tabindex="-1">常见误区 <a class="header-anchor" href="#常见误区" aria-label="Permalink to &quot;常见误区&quot;">​</a></h2><ul><li><strong>“微调可以解决所有知识问题”</strong>：知识更新和引用溯源更适合 <a href="/llm/rag-agent">RAG</a>；微调更擅长改变行为、格式和表达习惯。</li><li><strong>“对齐后模型就不会出错”</strong>：对齐改善行为倾向，不保证事实零错误。</li><li><strong>“预训练模型直接就能聊天”</strong>：预训练模型只会续写；对话能力主要来自指令微调和对齐。</li><li><strong>“RLHF 是人工在旁边逐条打分”</strong>：人工标注用于训练奖励模型；模型运行时的分数来自奖励模型，不是真人实时打分。</li><li><strong>“DPO 和 RLHF 是完全不同的两回事”</strong>：两者都基于人类偏好数据，核心差别只是是否显式训练一个奖励模型。</li><li><strong>“看一次成功演示就能证明微调有效”</strong>：需要用一组代表性样例，从正确率、格式稳定性、鲁棒性、拒答质量和成本延迟等维度评估。</li></ul><h2 id="自测问题" tabindex="-1">自测问题 <a class="header-anchor" href="#自测问题" aria-label="Permalink to &quot;自测问题&quot;">​</a></h2><h3 id="_1-预训练后的模型为什么-会写-但-不听话" tabindex="-1">1. 预训练后的模型为什么“会写”但“不听话”？ <a class="header-anchor" href="#_1-预训练后的模型为什么-会写-但-不听话" aria-label="Permalink to &quot;1. 预训练后的模型为什么“会写”但“不听话”？&quot;">​</a></h3><details><summary>查看答案</summary><p>预训练只教了“预测下一个 Token”，模型学到的是续写能力，不知道要按用户指令行事，也不知道哪些请求应该拒绝。指令遵循、安全边界和稳定的表达习惯，要靠指令微调和对齐来补齐。</p></details><h3 id="_2-rlhf-分哪几步-奖励模型在其中起什么作用" tabindex="-1">2. RLHF 分哪几步？奖励模型在其中起什么作用？ <a class="header-anchor" href="#_2-rlhf-分哪几步-奖励模型在其中起什么作用" aria-label="Permalink to &quot;2. RLHF 分哪几步？奖励模型在其中起什么作用？&quot;">​</a></h3><details><summary>查看答案</summary><p>三步：让模型对同一问题生成多个回答；人类比较回答好坏，形成偏好数据；用偏好数据训练奖励模型，再用强化学习让主模型生成更高分的回答。奖励模型把零散的人类偏好变成可自动计算的分数，替代人工在训练中持续打分。</p></details><h3 id="_3-让模型掌握公司固定的客服话术-和回答经常更新的产品资料-分别该怎么选" tabindex="-1">3. 让模型掌握公司固定的客服话术，和回答经常更新的产品资料，分别该怎么选？ <a class="header-anchor" href="#_3-让模型掌握公司固定的客服话术-和回答经常更新的产品资料-分别该怎么选" aria-label="Permalink to &quot;3. 让模型掌握公司固定的客服话术，和回答经常更新的产品资料，分别该怎么选？&quot;">​</a></h3><details><summary>查看答案</summary><p>固定话术、格式和语气属于行为习惯，适合微调；经常更新的资料放进参数很快过期，适合 RAG，由检索提供最新内容并支持引用来源。两者也可以组合：RAG 提供事实，微调稳定风格。</p></details><h2 id="关联阅读" tabindex="-1">关联阅读 <a class="header-anchor" href="#关联阅读" aria-label="Permalink to &quot;关联阅读&quot;">​</a></h2><ul><li><strong>前置概念：</strong> <a href="/llm/inference-decoding">推理与解码</a>说明模型生成内容时参数怎样参与计算。</li><li><strong>应用方向：</strong> <a href="/llm/rag-agent">RAG 与 Agent</a>解释知识不适合写进参数时怎样借助检索与工具。</li><li><strong>跨主题：</strong> <a href="/lora/basics">LoRA 入门</a>展示低秩适配怎样用较小增量调整模型。</li></ul><h2 id="官方或原始资料来源" tabindex="-1">官方或原始资料来源 <a class="header-anchor" href="#官方或原始资料来源" aria-label="Permalink to &quot;官方或原始资料来源&quot;">​</a></h2><ul><li><a href="https://arxiv.org/abs/2203.02155" target="_blank" rel="noreferrer">Ouyang 等：Training language models to follow instructions with human feedback</a>：InstructGPT 论文，SFT 与 RLHF 流程的原始出处。</li><li><a href="https://arxiv.org/abs/2204.05862" target="_blank" rel="noreferrer">Bai 等：Training a Helpful and Harmless Assistant with RLHF</a>：Anthropic 关于 RLHF 细节的经典技术报告。</li><li><a href="https://arxiv.org/abs/2305.18290" target="_blank" rel="noreferrer">Rafailov 等：Direct Preference Optimization</a>：DPO 的原始论文。</li><li><a href="https://huggingface.co/blog/rlhf" target="_blank" rel="noreferrer">Hugging Face：Illustrating RLHF</a>：对 RLHF 流程的图解式官方博客。</li><li><a href="https://huggingface.co/docs/trl" target="_blank" rel="noreferrer">Hugging Face TRL 文档</a>：实现 SFT、DPO、奖励模型等训练的官方库文档。</li><li><a href="https://en.wikipedia.org/wiki/Reinforcement_learning_from_human_feedback" target="_blank" rel="noreferrer">Wikipedia：Reinforcement learning from human feedback</a>：RLHF 概念、流程与局限的概览。</li></ul>`,55)])])}const u=t(i,[["render",n]]);export{g as __pageData,u as default};
